  /* ---------- the vector stand-in of the section (until the 3D stills exist, and without WebGL): the joint in cross-section ---------- */
  var VC = { back: '#8a877f', panel: '#cfcac0', edge: '#b9b4aa', old: '#8f8c86', rod: '#cfd3d6', tape: '#e6dcb9', prim: 'rgba(228,211,142,.7)', seal: '#6d7073', sealNB: '#8b8e90', clear: 'rgba(223,230,234,.6)', paint: '#ece8de', ink: '#111', water: '#9fd8f2' };
